------------------------------------------------------------------------------------enum{	kUnsupportedMac 	= -25001,	kCompiledWrong		= -25003,	kNoThreadManager	= -25004};//-------------------------------------------------------------------------------------------void main(){	try		{		InitUMacApp(8);		/* Check to see that we were compiled with the right options. FracApp absolutely		  positively needs to be compiled for Color QuickDraw and an FPU. We take		  advantage of 32-bit Color QuickDraw if it’s around, but we don’t require it.		  If FracApp was compiled with the wrong options, put up a dialog saying so,		  and quit the application. */#if !qPowerPC && qOldConfigurationFlags		if (!HasFPU_AC())			StdAlert(kCompiledWrong);		else#if !qNeedsFPU#error FracApp should be compiled with FPU option.#endif#endif		if (!HasThreadManager_AC())			StdAlert(kNoThreadManager);		else		{			/* InitToolBox has filled in a global variable call “gConfiguration”. This			  record contains a lot of information on what is available on the Macintosh we			  are running on. What we do next is call ValidateConfiguration to make sure			  that the machine features this program requires are actually available.			  ValidateConfiguration is self-configuring based on the compiler options you			  used to compile this program. If a feature is missing, ValidateConfiguration			  returns false. For instance, we compile FracApp with the -NeedsColorQD			  option. If we try to run FracApp on a machine that doesn’t have Color			  QuickDraw, then ValidateConfiguration returns false. Otherwise, it returns			  true, and we can safely run on this machine.					  We also test here to see if we are running on a machine that has an FPU. We			  don’t require that you actually COMPILE FracApp with the -NeedsFPU option,			  but there are some assembly routines that get compiled with 68881 code, and			  those pieces need to be run on a machine with an FPU. If you don’t put			  -NeedsFPU on the MABuild command line, then ValidateConfiguration won’t check			  for an FPU. Therefore, we do it ourself by hand. */					/* We now continue with the rest of MacApp’s initialization. Calling InitUMacApp			  is required. It takes a single parameter which is the number of times that			  MoreMasters should be called. InitUPrinting, InitUDialog, and InitUTEView			  setup their respective units, and only need to be called if you will be using			  any of their services. Forgetting to call InitUDialog is a particularly			  common problem that is tricky to detect. Many times, you’ll introduce a			  dialog to your program, and forget to call InitUDialog. You’ll also need to			  call InitUTEView if you use any TEditText items, not just TTEViews. If you			  forget to do any of this, you’ll find that the various views that appear in			  dialogs will get stripped out by the Linker, and your program will crash			  mysteriously. If you have a program that works in Debug mode, but not in			  Non-Debug, then this is most likely the problem. */					InitUPrinting();			InitUTEView();			InitUDialog();					/* Finally, we create our application object, initialize it, and run it. From			  this point on, MacApp is in control. When the user selects Quit from the			  menu, we come back to here, where all we have to do exit. */					TFracAppApplication gFracAppApplication(kFileType);			gFracAppApplication.Run();		}	}	catch(CException_AC& theException)	{		DoCatchMessageAndStop_AC(theException);		::BailOutAlert(theException);	}	catch(exception& ex)			{		DoCatchISOMessageAndStop_AC(ex);		::BailOutAlert(ex);	}	catch(...)	{		DoCatchForeignMessageAndStop_AC();		::BailOutAlert();	}}